const emergencyDefaults = [];
const ATTACHMENT_DB='reperto-poche-files',ATTACHMENT_STORE='attachments';
let attachmentDbPromise;
function attachmentDb(){
  if(!('indexedDB' in window))return Promise.reject(new Error('Le stockage de fichiers n’est pas disponible sur cet appareil.'));
  if(attachmentDbPromise)return attachmentDbPromise;
  attachmentDbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open(ATTACHMENT_DB,1);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(ATTACHMENT_STORE))db.createObjectStore(ATTACHMENT_STORE,{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('Ouverture du stockage impossible.'));});
  return attachmentDbPromise;
}
async function attachmentStorePut(file){const db=await attachmentDb();return new Promise((resolve,reject)=>{const request=db.transaction(ATTACHMENT_STORE,'readwrite').objectStore(ATTACHMENT_STORE).put(file);request.onsuccess=()=>resolve(file);request.onerror=()=>reject(request.error||new Error('Enregistrement du fichier impossible.'));});}
async function attachmentStoreGet(id){const db=await attachmentDb();return new Promise((resolve,reject)=>{const request=db.transaction(ATTACHMENT_STORE).objectStore(ATTACHMENT_STORE).get(id);request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>reject(request.error||new Error('Lecture du fichier impossible.'));});}
async function attachmentStoreKeys(){const db=await attachmentDb();return new Promise((resolve,reject)=>{const request=db.transaction(ATTACHMENT_STORE).objectStore(ATTACHMENT_STORE).getAllKeys();request.onsuccess=()=>resolve(request.result||[]);request.onerror=()=>reject(request.error||new Error('Lecture du stockage impossible.'));});}
async function attachmentStoreDelete(id){const db=await attachmentDb();return new Promise((resolve,reject)=>{const request=db.transaction(ATTACHMENT_STORE,'readwrite').objectStore(ATTACHMENT_STORE).delete(id);request.onsuccess=()=>resolve();request.onerror=()=>reject(request.error||new Error('Suppression du fichier impossible.'));});}
function dataUrlToBlob(data){const parts=String(data||'').split(','),header=parts.shift()||'',payload=parts.join(','),mime=(header.match(/^data:([^;]+)/)||[])[1]||'application/octet-stream',raw=header.includes(';base64')?atob(payload):decodeURIComponent(payload),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Blob([bytes],{type:mime});}
function blobToDataUrl(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Lecture du fichier impossible.'));reader.readAsDataURL(blob);});}
function walkAttachments(value,visitor){if(!value||typeof value!=='object')return;if(Array.isArray(value)){value.forEach(item=>walkAttachments(item,visitor));return;}if(value.attachment&&typeof value.attachment==='object')visitor(value.attachment,value);Object.values(value).forEach(item=>{if(item!==value.attachment)walkAttachments(item,visitor);});}
async function migrateLegacyAttachments(){
  const data=backupData();let moved=0;
  for(const value of Object.values(data))walkAttachments(value,attachment=>{if(attachment&&attachment.data)moved++;});
  if(!moved)return 0;
  for(const value of Object.values(data)){const pending=[];walkAttachments(value,(attachment,parent)=>{if(!attachment||!attachment.data)return;pending.push((async()=>{const blob=dataUrlToBlob(attachment.data),id=attachment.id||uid('file');await attachmentStorePut({id,name:attachment.name||'fichier',type:attachment.type||blob.type||'application/octet-stream',blob,updatedAt:Date.now()});parent.attachment={id,name:attachment.name||'fichier',type:attachment.type||blob.type||'application/octet-stream',size:blob.size,storage:'indexeddb'};})());});for(const job of pending)await job;}
  Object.entries(data).forEach(([key,value])=>localStorage.setItem(key,JSON.stringify(value)));
  return moved;
}
async function cleanupOrphanAttachments(){try{const used=new Set();Object.values(backupData()).forEach(value=>walkAttachments(value,attachment=>{if(attachment&&attachment.id)used.add(attachment.id);}));for(const id of await attachmentStoreKeys())if(!used.has(id))await attachmentStoreDelete(id);}catch{}}
const get = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key) || 'null') || fallback; } catch { return fallback; } };
const set = (key, value) => localStorage.setItem(key, JSON.stringify(value));
// Favoris v43 : uniquement des références, donc aucune duplication ni perte de données.
const getFavorites = () => get('rp-favorites', []);
const setFavorites = value => set('rp-favorites', value);
const favoriteKey = (type,id,extra='') => `${type}|${id}${extra?`|${extra}`:''}`;
const isFavorite = (type,id,extra='') => getFavorites().some(item=>item.key===favoriteKey(type,id,extra));
function toggleFavorite(item){const list=getFavorites(),i=list.findIndex(entry=>entry.key===item.key);if(i>=0){list.splice(i,1);toast('Retiré des favoris');}else{list.unshift({...item,createdAt:Date.now()});toast('Ajouté aux favoris');}setFavorites(list);}
const favoriteButton = (type,id,label,extra='') => `<button class="favorite-toggle ${isFavorite(type,id,extra)?'active':''}" data-favorite="${escape(favoriteKey(type,id,extra))}" aria-label="${isFavorite(type,id,extra)?'Retirer':'Ajouter'} ${escape(label)} ${isFavorite(type,id,extra)?'des':'aux'} favoris"><span>${isFavorite(type,id,extra)?'★':'☆'}</span></button>`;
// Profil facultatif, stocké uniquement sur cet appareil.
