const profileFirstName = () => String(getProfile().firstName || '').trim().slice(0,40);
const profileLastName = () => String(getProfile().lastName || '').trim().slice(0,40);
const profileInitial = () => { const firstName=profileFirstName(), lastName=profileLastName(); const initials=`${firstName.slice(0,1)}${lastName.slice(0,1)}`.toLocaleUpperCase('fr'); return initials ? escape(initials) : '◯'; };
const profileGreeting = () => { const firstName=profileFirstName(); return firstName ? `Bonjour, ${escape(firstName)}` : 'Bonjour'; };
const getMeds = () => get('rp-meds', medDefaults);
const setMeds = value => set('rp-meds', value);
const getEstablishments = () => get('rp-establishments', establishmentDefaults);
const setEstablishments = value => set('rp-establishments', value);
const getPlanning = () => get('rp-planning', planningDefaults);
const setPlanning = value => set('rp-planning', value);
const getSurgerySpecialties = () => get('rp-surgery-specialties', surgerySpecialtyDefaults);
const setSurgerySpecialties = value => set('rp-surgery-specialties', value);
const getAnesthesiaTerrains = () => get('rp-anesthesia-terrains', anesthesiaTerrainDefaults);
const setAnesthesiaTerrains = value => set('rp-anesthesia-terrains', value);
const backupCollections = {
  'rp-meds': medDefaults,
  'rp-establishments': establishmentDefaults,
  'rp-planning': planningDefaults,
  'rp-languages': languageDefaults,
  'rp-protocols': protocolDefaults,
  'rp-notes': noteDefaults,
  'rp-surgery': surgeryDefaults,
  'rp-surgery-specialties': surgerySpecialtyDefaults,
  'rp-anesthesia-terrains': anesthesiaTerrainDefaults,
  'rp-pediatrics': pediatricsDefaults,
  'rp-emergencies': emergencyDefaults,
  'rp-favorites': []
};
const backupCollectionKeys = Object.keys(backupCollections);
// Les sauvegardes antérieures aux nouvelles rubriques restent restaurables :
// les collections absentes sont créées vides, sans toucher aux données existantes.
const requiredBackupKeys = backupCollectionKeys.filter(key=>!['rp-surgery','rp-surgery-specialties','rp-anesthesia-terrains','rp-pediatrics','rp-emergencies','rp-favorites'].includes(key));
function backupData(){
  const data=Object.fromEntries(backupCollectionKeys.map(key=>[key,get(key,backupCollections[key])]));
  for(let index=0;index<localStorage.length;index++){const key=localStorage.key(index);if(!key||!key.startsWith('rp-')||key in data)continue;try{data[key]=JSON.parse(localStorage.getItem(key));}catch{}}
  return data;
}
async function makeBackup(){
  const data=backupData(),attachments={};const jobs=[];
  Object.values(data).forEach(value=>walkAttachments(value,attachment=>{if(attachment&&attachment.id&&!attachment.data)jobs.push((async()=>{const stored=await attachmentStoreGet(attachment.id);if(stored&&stored.blob)attachments[attachment.id]={name:stored.name||attachment.name,type:stored.type||attachment.type||stored.blob.type,data:await blobToDataUrl(stored.blob)};})());}));
  await Promise.all(jobs);
  return {app:'Réperto’Poche',format:'backup',version:3,exportedAt:new Date().toISOString(),data,attachments};
}
function validBackup(backup){
  return !!(backup&&backup.app==='Réperto’Poche'&&backup.format==='backup'&&backup.data&&typeof backup.data==='object'&&!Array.isArray(backup.data)&&requiredBackupKeys.every(key=>Array.isArray(backup.data[key]))&&backupCollectionKeys.every(key=>!(key in backup.data)||Array.isArray(backup.data[key])));
}
async function downloadBackup(){
  try{toast('Préparation de la sauvegarde…');const backup=await makeBackup(),stamp=new Date().toISOString().slice(0,10),blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');
  link.href=url;link.download=`Reperto-Poche-sauvegarde-${stamp}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sauvegarde téléchargée : garde-la dans Fichiers ou iCloud Drive');}catch(error){toast(error.message||'Sauvegarde impossible.');}
}
async function restoreBackup(backup){
  const keys=Object.keys(backup.data).filter(key=>key.startsWith('rp-')),before=Object.fromEntries(keys.map(key=>[key,localStorage.getItem(key)]));
  try{for(const [id,item] of Object.entries(backup.attachments||{})){if(!item||!item.data)continue;const blob=dataUrlToBlob(item.data);await attachmentStorePut({id,name:item.name||'fichier',type:item.type||blob.type||'application/octet-stream',blob,updatedAt:Date.now()});}keys.forEach(key=>localStorage.setItem(key,JSON.stringify(backup.data[key])));await migrateLegacyAttachments();await cleanupOrphanAttachments();}
  catch(error){keys.forEach(key=>before[key]===null?localStorage.removeItem(key):localStorage.setItem(key,before[key]));throw new Error('Espace insuffisant : la restauration n’a pas été appliquée.');}
}
function chooseBackup(){
  const input=document.createElement('input');input.type='file';input.accept='application/json,.json';
  input.onchange=()=>{const file=input.files&&input.files[0];if(!file)return;if(file.size>100*1024*1024)return toast('Cette sauvegarde dépasse 100 Mo.');const reader=new FileReader();reader.onload=()=>{try{const backup=JSON.parse(reader.result);if(!validBackup(backup))throw new Error();const date=backup.exportedAt?new Date(backup.exportedAt).toLocaleDateString('fr-FR'):'date inconnue';menuSheet('Restaurer cette sauvegarde ?',[{id:'restore',label:'Restaurer mes données',hint:`Sauvegarde du ${date} · remplace les données présentes dans le fichier`,icon:'↻',danger:true,action:async()=>{try{await restoreBackup(backup);profile();toast('Sauvegarde restaurée sur cet iPhone');}catch(error){toast(error.message);}}},{id:'cancel',label:'Annuler',hint:'Conserver les données actuelles',icon:'‹',action:()=>{}}]);}catch{toast('Ce fichier n’est pas une sauvegarde Réperto’Poche valide.');}};reader.onerror=()=>toast('Lecture du fichier impossible.');reader.readAsText(file);};input.click();
}
const uid = prefix => `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}`;
const escape = text => String(text || '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const logo = () => '<div class="brand"><i class="logo" aria-hidden="true"></i><span>Réperto’Poche</span></div>';
const nav = (active='home') => `<nav class="nav" aria-label="Navigation principale">
  <button class="${active==='home'?'active':''}" data-go="home"><span>⌂</span>Accueil</button>
  <button class="${active==='search'?'active':''}" data-go="search"><span>⌕</span>Recherche</button>
  <button class="${active==='planning'?'active':''}" data-go="planning"><span>▣</span>Planning</button>
</nav>`;
const topbar = () => `<header class="top">${logo()}<button class="avatar ${profileFirstName()?'has-name':'neutral'}" data-go="profile" aria-label="Mon profil">${profileInitial()}</button></header>`;
const category = (cls, icon, title, meta, target) => `<button class="folder ${cls}" data-go="${target}"><span class="icon">${icon}</span><h2>${title}</h2><p>${meta}</p></button>`;
const searchText = value => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr');
const sortByName = (a,b) => searchText(a.name || a.title).localeCompare(searchText(b.name || b.title),'fr',{numeric:true});
const sortedContacts = establishment => [...(establishment.contacts || [])].sort((a,b) => a.department.localeCompare(b.department,'fr'));
const resourceTags=['Accueil','Protocoles','Plans / accès','Administratif','Urgence','À vérifier'];
const contactRoles=['Anesthésiste','Chirurgien','Encadrement'];
const contactGrades=['Praticien hospitalier','Interne','Intérimaire'];
// Compatibilité : les anciens fichiers uniques deviennent une ressource, sans perdre de donnée.
const placeResources = place => Array.isArray(place.resources) ? place.resources : (place.attachment ? [{id:'legacy-resource',title:place.attachment.name,attachment:place.attachment,tags:[]}] : []);
const resourceMatchesTag = (resource,tag) => !tag || (resource.tags||[]).includes(tag);
const resourceTypeLabel = attachment => isPhotoAttachment(attachment) ? 'Photo' : 'Fichier';
const isPhotoAttachment = attachment => /^image\//i.test((attachment||{}).type||'') || /\.(jpe?g|png|gif|webp|heic|heif)$/i.test((attachment||{}).name||'');
const contactRoleLabel = contact => [contact.role,contact.grade].filter(Boolean).join(' · ');

function home(){
  const est = getEstablishments(); const events = getPlanning(), favorites=getFavorites();
  app.innerHTML = `${topbar()}<p class="eyebrow">${profileGreeting()}</p><h1 class="headline">Tout retrouver,<br>même dans l’urgence.</h1><p class="sub">Ton carnet professionnel, toujours dans la poche.</p>
  <label class="search"><span>⌕</span><input id="global-search" placeholder="Rechercher dans Réperto’Poche" autocomplete="off" /></label>
  <section id="home-folders" class="grid">${category('favorites','★','Favoris',favorites.length?`${favorites.length} repère${favorites.length>1?'s':''}`:'À épingler','favorites')}${category('emergencies','!','Urgences',`${get('rp-emergencies', emergencyDefaults).length} repère${get('rp-emergencies', emergencyDefaults).length>1?'s':''}`,'emergencies')}${category('est','⌂','Établissements',`${est.length} lieux`,'establishments')}${category('med','●','Médicaments',`${getMeds().length} fiches`,'meds')}${category('surgery','✚','Chirurgies',`${getSurgerySpecialties().length} spécialité${getSurgerySpecialties().length>1?'s':''}`,'surgery')}${category('anesthesia','◌','Anesthésies',`${getAnesthesiaTerrains().length} terrain${getAnesthesiaTerrains().length>1?'s':''}`,'anesthesia')}${category('pediatrics','♧','Pédiatrie',`${get('rp-pediatrics', pediatricsDefaults).length} repère${get('rp-pediatrics', pediatricsDefaults).length>1?'s':''}`,'pediatrics')}${category('lang','文','Langues',`${get('rp-languages', languageDefaults).length} dossiers`,'languages')}${category('docs','▤','Protocoles',`${get('rp-protocols', protocolDefaults).length} document${get('rp-protocols', protocolDefaults).length>1?'s':''}`,'protocols')}${category('notes','✎','Notes rapides',`${get('rp-notes', noteDefaults).length} note${get('rp-notes', noteDefaults).length>1?'s':''}`,'notes')}${category('plan','□','Planning',events.length ? `${events.length} créneau${events.length>1?'x':''}` : 'À organiser','planning')}</section><section id="home-search-results" class="search-results" hidden></section>${nav('home')}`;
  $('#global-search').addEventListener('input', e => globalSearch(e.target.value)); bind();
}

function favoriteItem(item){
  const key=item.key||'', [type,id]=key.split('|');
  if(type==='med'){const med=getMeds().find(x=>x.id===id);return med?`<button class="item" data-med="${med.id}"><span class="item-icon med-icon">●</span><span class="item-main"><h2>${escape(med.name)}</h2><p>${escape(med.class||'Médicament')}</p></span><span class="chev">›</span></button>`:'';}
  if(type==='est'){const place=getEstablishments().find(x=>x.id===id);return place?`<button class="item" data-est="${place.id}"><span class="item-icon est-icon">⌂</span><span class="item-main"><h2>${escape(place.name)}</h2><p>${escape(place.city||'Établissement')}</p></span><span class="chev">›</span></button>`:'';}
  if(type==='contact'){const place=getEstablishments().find(x=>x.id===item.extra),contact=place&&(place.contacts||[]).find(x=>x.id===id);return contact?`<button class="item" data-favorite-open="contact|${place.id}"><span class="item-icon est-icon">⌂</span><span class="item-main"><h2>${escape(contact.department)}</h2><p>${escape(place.name)} · ${escape(contact.phone||'À renseigner')}</p></span><span class="chev">›</span></button>`:'';}
  if(type==='place-resource'){const place=getEstablishments().find(x=>x.id===item.extra),resource=place&&placeResources(place).find(x=>x.id===id);return resource?`<button class="item" data-favorite-open="place-resource|${place.id}"><span class="item-icon est-icon">⌇</span><span class="item-main"><h2>${escape(resource.title)}</h2><p>${escape(place.name)} · fichier</p></span><span class="chev">›</span></button>`:'';}
  if(type==='resource'){const kind=item.extra,config=resourceConfig[kind],resource=config&&get(config.key,config.fallback).find(x=>x.id===id);return resource?`<button class="item" data-favorite-open="resource|${escape(kind)}"><span class="item-icon med-icon">▤</span><span class="item-main"><h2>${escape(resource.title)}</h2><p>${escape(config.title)}</p></span><span class="chev">›</span></button>`:'';}
  return '';
}
function favoritesPage(){
  const items=getFavorites(),cards=items.map(favoriteItem).filter(Boolean);
  app.innerHTML=`${topbar()}${sectionTitle('Favoris','Tes repères à retrouver immédiatement','home')}<p class="helper">Épingle un médicament ou un établissement avec l’étoile. Tes données restent rangées dans leur rubrique d’origine.</p><section class="list favorites-list">${cards.length?cards.join(''):empty('Aucun favori pour le moment. Ouvre une fiche et touche l’étoile.')}</section>${nav()}`;
  bind();
}

function profile(){
  const firstName=profileFirstName();
  app.innerHTML=`${topbar()}${sectionTitle('Mon profil','Vos préférences restent sur cet appareil.','home')}<section class="profile-identity"><span class="profile-avatar ${firstName?'has-name':'neutral'}">${profileInitial()}</span><div><h2>Me reconnaître</h2><p>Ce prénom est facultatif et reste uniquement sur cet iPhone.</p></div></section><form id="profile-form" class="profile-form"><label class="field"><span>Prénom</span><input name="firstName" maxlength="40" value="${escape(firstName)}" placeholder="Ex. Claire" autocomplete="given-name"></label><label class="field"><span>Nom de famille <small>(facultatif)</small></span><input name="lastName" maxlength="40" value="${escape(profileLastName())}" placeholder="Ex. Martin" autocomplete="family-name"></label><button class="profile-save" type="submit">Enregistrer</button></form><section class="profile-data"><h2>Mes données</h2><div class="profile-local-note"><span>⌁</span><p><strong>Vos données restent sur votre appareil.</strong><br>Aucun compte ni e-mail ne sont nécessaires.</p></div><section class="backup-actions"><button class="backup-action" data-backup-export><span class="backup-action-icon">↓</span><span><strong>Sauvegarder mes données</strong><small>Créer une copie dans Fichiers ou iCloud Drive</small></span></button><button class="backup-action restore" data-backup-import><span class="backup-action-icon">↑</span><span><strong>Restaurer une sauvegarde</strong><small>Remplacer les données par une copie</small></span></button></section></section><section class="profile-help"><h2>Aide</h2><p>À propos de Réperto’Poche</p><small>Version test 0.38</small></section>${nav()}`;
  const form=$('#profile-form');
  form.addEventListener('submit',event=>{event.preventDefault();const values=new FormData(form);const firstName=String(values.get('firstName')||'').trim().replace(/\s+/g,' ').slice(0,40);const lastName=String(values.get('lastName')||'').trim().replace(/\s+/g,' ').slice(0,40);set('rp-profile',{firstName,lastName});toast(firstName||lastName?'Profil enregistré sur cet iPhone':'Profil enregistré');profile();});
  bind();
}

function medMatches(med,query){ return searchText(`${med.name} ${med.class} ${med.indication} ${med.mechanism} ${med.contra} ${med.dose}`).includes(searchText(query)); }
function medClassName(med){ return String(med.class||'').trim() || 'Sans classe'; }
function medClasses(){
  const counts=new Map();
  getMeds().forEach(med=>{const name=medClassName(med);counts.set(name,(counts.get(name)||0)+1);});
  return [...counts].sort((a,b)=>searchText(a[0]).localeCompare(searchText(b[0]),'fr',{numeric:true}));
}
