function bindHold(){document.querySelectorAll('[data-hold]').forEach(element=>{let timer;let held=false;const stop=()=>{clearTimeout(timer);};element.addEventListener('pointerdown',()=>{held=false;timer=setTimeout(()=>{held=true;entryMenu(element.dataset.hold);},650);});element.addEventListener('pointerup',stop);element.addEventListener('pointerleave',stop);element.addEventListener('pointercancel',stop);element.addEventListener('click',event=>{if(held){event.preventDefault();event.stopImmediatePropagation();held=false;}},true);element.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();entryMenu(element.dataset.hold);}});});}
function bind(){
  document.querySelectorAll('[data-go]').forEach(button=>button.onclick=()=>{const target=button.dataset.go;if(target==='home')home();else if(target==='meds')meds();else if(target==='establishments')establishments();else if(target==='planning')planning();else if(target==='remuneration')remuneration();else if(target==='search')searchPage();else if(target==='profile')profile();else if(target==='favorites')favoritesPage();else if(target==='surgery')surgery();else if(target==='surgery-specialty')surgery();else if(target==='anesthesia')anesthesia();else if(target==='anesthesia-terrain')anesthesia();else if(['languages','protocols','notes','pediatrics','emergencies'].includes(target))resourcePage(target);});
  document.querySelectorAll('[data-favorite]').forEach(button=>button.onclick=()=>{const [type,id,...rest]=button.dataset.favorite.split('|');const item={key:button.dataset.favorite,type,id,label:button.closest('.section-head')?.querySelector('h1')?.textContent||'Repère',extra:rest.join('|')};toggleFavorite(item);if(type==='med')medDetail(id);else if(type==='est')establishmentDetail(id);else favoritesPage();});
  document.querySelectorAll('[data-favorite-open]').forEach(button=>button.onclick=()=>{const [type,id]=button.dataset.favoriteOpen.split('|');if(type==='contact'||type==='place-resource')establishmentDetail(id);else if(type==='resource')resourcePage(id);});
  document.querySelectorAll('[data-med]').forEach(button=>button.onclick=()=>medDetail(button.dataset.med));
  document.querySelectorAll('[data-med-class]').forEach(button=>button.onclick=()=>meds(button.dataset.medClass));
  document.querySelectorAll('[data-est]').forEach(button=>button.onclick=()=>establishmentDetail(button.dataset.est));
  document.querySelectorAll('[data-add-med]').forEach(button=>button.onclick=()=>medForm());
  document.querySelectorAll('[data-edit-med]').forEach(button=>button.onclick=()=>medForm(getMeds().find(item=>item.id===button.dataset.editMed)));
  document.querySelectorAll('[data-add-est]').forEach(button=>button.onclick=()=>establishmentForm());
  document.querySelectorAll('[data-edit-est]').forEach(button=>button.onclick=()=>establishmentForm(getEstablishments().find(item=>item.id===button.dataset.editEst)));
  document.querySelectorAll('[data-add-contact]').forEach(button=>button.onclick=()=>contactForm(button.dataset.addContact));
  document.querySelectorAll('[data-add-place-resource]').forEach(button=>button.onclick=()=>placeResourceForm(button.dataset.addPlaceResource));
  document.querySelectorAll('[data-place-tag]').forEach(button=>button.onclick=()=>{const placeId=button.closest('[data-current-place]')?.dataset.currentPlace;if(placeId)establishmentDetail(placeId,button.dataset.placeTag);});
  document.querySelectorAll('[data-edit-contact]').forEach(button=>button.onclick=()=>{const [placeId,contactId]=button.dataset.editContact.split('|');const place=getEstablishments().find(item=>item.id===placeId);contactForm(placeId,(place.contacts||[]).find(item=>item.id===contactId));});
  document.querySelectorAll('[data-add-event]').forEach(button=>button.onclick=()=>eventForm());
  document.querySelectorAll('[data-add-event-date]').forEach(button=>button.onclick=()=>eventForm(null,button.dataset.addEventDate));
  document.querySelectorAll('[data-edit-event]').forEach(button=>button.onclick=()=>eventForm(getPlanning().find(item=>item.id===button.dataset.editEvent)));
  document.querySelectorAll('[data-language]').forEach(button=>button.onclick=()=>languageDetail(button.dataset.language));
  document.querySelectorAll('[data-anesthesia-terrain]').forEach(button=>button.onclick=()=>anesthesiaTerrain(button.dataset.anesthesiaTerrain));
  document.querySelectorAll('[data-anesthesia-fiche]').forEach(button=>button.onclick=()=>{const [terrainId,ficheId]=button.dataset.anesthesiaFiche.split('|');anesthesiaFicheDetail(terrainId,ficheId);});
  document.querySelectorAll('[data-add-anesthesia-terrain]').forEach(button=>button.onclick=()=>anesthesiaTerrainForm());
  document.querySelectorAll('[data-add-anesthesia-general]').forEach(button=>button.onclick=()=>anesthesiaGeneralForm(button.dataset.addAnesthesiaGeneral));
  document.querySelectorAll('[data-add-anesthesia-fiche]').forEach(button=>button.onclick=()=>anesthesiaFicheForm(button.dataset.addAnesthesiaFiche));
  document.querySelectorAll('[data-surgery-specialty]').forEach(button=>button.onclick=()=>surgerySpecialty(button.dataset.surgerySpecialty));
  document.querySelectorAll('[data-surgery-intervention]').forEach(button=>button.onclick=()=>{const [specialtyId,interventionId]=button.dataset.surgeryIntervention.split('|');surgeryInterventionDetail(specialtyId,interventionId);});
  document.querySelectorAll('[data-add-surgery-specialty]').forEach(button=>button.onclick=()=>surgerySpecialtyForm());
  document.querySelectorAll('[data-add-surgery-general]').forEach(button=>button.onclick=()=>surgeryGeneralForm(button.dataset.addSurgeryGeneral));
  document.querySelectorAll('[data-add-surgery-intervention]').forEach(button=>button.onclick=()=>surgeryInterventionForm(button.dataset.addSurgeryIntervention));
  document.querySelectorAll('[data-surgery-legacy]').forEach(button=>button.onclick=surgeryLegacy);
  document.querySelectorAll('[data-delete-legacy-surgery]').forEach(button=>button.onclick=()=>{const item=get('rp-surgery',surgeryDefaults).find(entry=>entry.id===button.dataset.deleteLegacySurgery);if(!item)return;surgeryLegacy();deleteEntry('ce repère précédent',()=>{set('rp-surgery',get('rp-surgery',surgeryDefaults).filter(entry=>entry.id!==item.id));surgeryLegacy();});});
  document.querySelectorAll('[data-clear-legacy-surgery]').forEach(button=>button.onclick=()=>deleteEntry('tous les repères de chirurgie précédents',()=>{set('rp-surgery',[]);surgery();}));
  document.querySelectorAll('[data-add-resource]').forEach(button=>button.onclick=()=>resourceForm(button.dataset.addResource));
  document.querySelectorAll('[data-add-language-note]').forEach(button=>button.onclick=()=>languageNoteForm(button.dataset.addLanguageNote));
  document.querySelectorAll('[data-day]').forEach(button=>button.onclick=()=>planning(button.dataset.day.slice(0,7),button.dataset.day));
  document.querySelectorAll('[data-today]').forEach(button=>button.onclick=()=>{const today=new Date().toISOString().slice(0,10);planning(today.slice(0,7),today);});
  document.querySelectorAll('[data-month]').forEach(button=>button.onclick=()=>planning(button.dataset.month));
  document.querySelectorAll('[data-backup-export]').forEach(button=>button.onclick=downloadBackup);
  document.querySelectorAll('[data-backup-import]').forEach(button=>button.onclick=chooseBackup);
  document.querySelectorAll('[data-attachment-open]').forEach(link=>link.addEventListener('click',openAttachment));
  bindHold();
}
// Empêche le menu iPhone Copier/Rechercher sur les fiches ; les champs restent éditables.
document.addEventListener('contextmenu',event=>{
  if(!event.target.closest('input, textarea, select, [contenteditable="true"]')) event.preventDefault();
});
if('serviceWorker' in navigator){
  let refreshing=false;
  navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshing){refreshing=true;window.location.reload();}});
  navigator.serviceWorker.register('sw.js?v=47.3',{updateViaCache:'none'}).then(registration=>registration.update()).catch(()=>{});
}
async function startApp(){let moved=0;try{moved=await migrateLegacyAttachments();await cleanupOrphanAttachments();}catch(error){console.warn('Migration des fichiers',error);}home();if(moved)toast(`${moved} fichier${moved>1?'s':''} déplacé${moved>1?'s':''} vers le stockage étendu`);}
startApp();


// RÉMUNÉRATION V44 — intégration locale, hors ligne et sans compte.
// Les montants sont des estimations personnelles : le contrat et le bulletin de paie restent la référence.
function rpMoney(value){return new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value)||0);}
function rpRemuneration(place={}){const r=place.remuneration||{};return {contractType:r.contractType==='interim'?'interim':'vacation',rate:Math.max(0,Number(r.rate)||0),rateBasis:r.rateBasis==='brut'?'brut':'net',pauseMinutes:Math.max(0,Number(r.pauseMinutes)||0),interimBonusPct:Math.max(0,Number(r.interimBonusPct)===0?0:(Number(r.interimBonusPct)||20)),interimNetPct:Math.min(100,Math.max(0,Number(r.interimNetPct)===0?0:(Number(r.interimNetPct)||79.9)))};}
function rpReady(r){return Number(r&&r.rate)>0;}
function rpLabel(r){if(!rpReady(r))return 'Rémunération à régler';const type=r.contractType==='interim'?'Intérim':'Vacation';const basis=r.rateBasis==='brut'?(r.contractType==='interim'?'brut → net avant impôt estimé':'brut'):'net estimé';return `${type} · ${basis} · ${rpMoney(r.rate)}/h`;}
function rpSnapshot(event){return event&&event.remunerationSnapshot&&rpReady(event.remunerationSnapshot)?event.remunerationSnapshot:null;}
function rpPaidMinutes(event){const r=rpSnapshot(event),duration=eventDurationMinutes(event);return r?Math.max(0,duration-Math.min(duration,Number(r.pauseMinutes)||0)):0;}
function rpEstimate(event,days=eventDays(event)){const r=rpSnapshot(event);if(!r||event.type!=='work')return 0;const hours=(rpPaidMinutes(event)/60)*Math.max(0,days),gross=hours*Number(r.rate)*(1+(r.contractType==='interim'?(Number(r.interimBonusPct)||0)/100:0));return r.contractType==='interim'&&r.rateBasis==='brut'?gross*((Number(r.interimNetPct)||0)/100):gross;}
function rpEstimateLabel(event,days=1){const r=rpSnapshot(event);if(!r)return '';const total=rpEstimate(event,days);return `${rpMoney(total)} estimés${r.contractType==='interim'?(r.rateBasis==='brut'?` · net avant impôt · ${Number(r.interimNetPct)||0} %`:` · +${Number(r.interimBonusPct)||0} % intérim`):''}`;}
function rpHourlyEstimate(event){const r=rpSnapshot(event);if(!r||event.type!=='work')return 0;let hourly=Number(r.rate)||0;if(r.contractType==='interim'){hourly*=1+(Number(r.interimBonusPct)||0)/100;if(r.rateBasis==='brut')hourly*=(Number(r.interimNetPct)||0)/100;}return hourly;}
function rpLivePayState(event,date=new Date().toISOString().slice(0,10)){
 const r=rpSnapshot(event);if(!r||event.type!=='work'||!event.start||!event.end)return null;
 const start=new Date(`${date}T${event.start}:00`),end=new Date(`${date}T${event.end}:00`);if(Number.isNaN(start)||Number.isNaN(end))return null;if(end<=start)end.setDate(end.getDate()+1);
 const totalMs=end-start,paidMs=Math.max(0,totalMs-Math.min(totalMs,(Number(r.pauseMinutes)||0)*60000)),now=Date.now(),elapsed=Math.max(0,Math.min(totalMs,now-start));
 // The unpaid meal break is spread over the shift so the amount rises continuously and reaches the existing final estimate.
 const paidElapsed=totalMs?elapsed*paidMs/totalMs:0,earned=paidElapsed/3600000*rpHourlyEstimate(event);
 return {status:now<start?'upcoming':now>=end?'finished':'running',earned,final:rpEstimate(event),progress:totalMs?elapsed/totalMs:0,start,end,pause:Number(r.pauseMinutes)||0};
}
function rpLivePayCard(events,date){
 const event=events.find(item=>{const state=rpLivePayState(item,date);return state&&state.status==='running';});
 if(!event)return '';
 const state=rpLivePayState(event,date),r=rpSnapshot(event),pause=state.pause?` · pause de ${state.pause} min déduite`:'';
 return `<section class="live-pay-card" data-live-event="${event.id}" aria-live="polite"><div class="live-pay-top"><span class="live-pay-pulse"></span><div><p>Garde en cours</p><h2>${escape(event.title)}</h2><small>${escape(event.place||r.establishmentName||'Établissement à préciser')}</small></div><span class="live-pay-icon">€</span></div><div class="live-pay-amount"><span>Gagné à cet instant</span><strong data-live-earned>${rpMoney(state.earned)}</strong></div><div class="live-pay-progress" role="progressbar" aria-label="Avancement de la garde" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(state.progress*100)}"><i data-live-progress style="width:${Math.round(state.progress*100)}%"></i></div><div class="live-pay-footer"><span data-live-time>${event.start} – ${event.end}${pause}</span><strong>Fin estimée : ${rpMoney(state.final)}</strong></div><p class="live-pay-note">Montant lissé sur la garde, pour intégrer la pause non payée.</p></section>`;
}
function rpUpdateLivePayCounters(){document.querySelectorAll('[data-live-event]').forEach(card=>{const event=getPlanning().find(item=>item.id===card.dataset.liveEvent),state=event&&rpLivePayState(event);if(!state||state.status!=='running'){card.remove();return;}const earned=card.querySelector('[data-live-earned]'),progress=card.querySelector('[data-live-progress]'),bar=card.querySelector('[role="progressbar"]');if(earned)earned.textContent=rpMoney(state.earned);if(progress)progress.style.width=`${Math.round(state.progress*100)}%`;if(bar)bar.setAttribute('aria-valuenow',String(Math.round(state.progress*100)));});}

function rpDaysInMonth(event,cursor){const [year,month]=cursor.split('-').map(Number),first=`${cursor}-01`,last=`${cursor}-${String(new Date(year,month,0).getDate()).padStart(2,'0')}`,start=eventStart(event)>first?eventStart(event):first,end=eventEnd(event)<last?eventEnd(event):last;return start>end?0:Math.round((new Date(`${end}T12:00:00`)-new Date(`${start}T12:00:00`))/86400000)+1;}
function rpSnapshotFromPlace(place){const r=rpRemuneration(place);return rpReady(r)?{establishmentId:place.id,establishmentName:place.name,...r}:null;}

function establishmentDetailBase(id,activeTag=''){
 const place=getEstablishments().find(item=>item.id===id);if(!place)return establishments();
 const contacts=sortedContacts(place),resources=placeResources(place),visibleResources=resources.filter(resource=>resourceMatchesTag(resource,activeTag)),r=rpRemuneration(place);
 const chips=['Tous',...resourceTags].map(tag=>`<button class="tag-filter ${(!activeTag&&tag==='Tous')||activeTag===tag?'selected':''}" data-place-tag="${escape(tag==='Tous'?'':tag)}">${escape(tag)}</button>`).join('');
 const pay=`<section class="remuneration-card"><div class="remuneration-main"><span class="pay-card-icon">€</span><div><h2>Rémunération estimée</h2><p>${escape(rpLabel(r))}</p><small>${rpReady(r)?`Pause : ${r.pauseMinutes} min${r.contractType==='interim'?` · majoration : +${r.interimBonusPct} % · net avant impôt : ${r.interimNetPct} %`:''}`:'Configure le taux pour l’utiliser dans le planning.'}</small></div></div><button class="secondary-button" data-edit-est="${place.id}">${rpReady(r)?'Modifier':'Configurer'}</button></section>`;
 app.innerHTML=`${topbar()}${sectionTitle(escape(place.name),escape(place.city||'Établissement'),'establishments')}<div class="place-summary holdable" tabindex="0" role="button" data-hold="est|${place.id}"><span class="item-icon est-icon">⌂</span><div><strong>${escape(place.service||'Service à renseigner')}</strong><p class="multiline">${escape(place.note||'Ajoute ici tes repères pratiques.')}</p></div></div>${pay}<p class="helper">Maintiens un établissement, une ressource ou un contact pour le modifier ou le supprimer.</p><div class="subsection-head"><div><h2>Ressources</h2><p>${resources.length} fichier${resources.length>1?'s':''} ou photo${resources.length>1?'s':''}</p></div><button class="small-add" data-add-place-resource="${place.id}" aria-label="Ajouter un fichier ou une photo">+</button></div><div class="tag-filters" data-current-place="${place.id}" aria-label="Filtrer les ressources">${chips}</div><section class="list place-resources">${visibleResources.length?visibleResources.map(resource=>resourceCard(place.id,resource)).join(''):empty(activeTag?`Aucune ressource avec le tag « ${escape(activeTag)} ».`:'Ajoute un PDF, un document ou une photo.')}</section><div class="subsection-head"><div><h2>Annuaire téléphonique</h2><p>${contacts.length} contact${contacts.length>1?'s':''} · ordre alphabétique</p></div><button class="small-add" data-add-contact="${place.id}" aria-label="Ajouter un contact">+</button></div><section class="list contacts">${contacts.length?contacts.map(c=>`<article class="contact-card holdable" tabindex="0" role="button" data-hold="contact|${place.id}|${c.id}"><span class="contact-letter">${escape(c.department.slice(0,1).toUpperCase())}</span><div class="item-main"><h2>${escape(c.department)}</h2><p>${escape(c.phone||'À renseigner')}</p>${contactRoleLabel(c)?`<span class="contact-role">${escape(contactRoleLabel(c))}</span>`:''}${c.note?`<p class="contact-note">${escape(c.note)}</p>`:''}</div></article>`).join(''):empty('Aucun contact pour le moment.')}</section>${nav()}`;bind();
}

function establishmentForm(existing){
 const place=existing||{name:'',city:'',service:'',note:'',contacts:[],resources:[]},r=rpRemuneration(place);
 const remunerationFields=`<fieldset class="remuneration-fields"><legend>Rémunération estimée <small>facultatif</small></legend><div class="field"><label>Type de contrat</label><select name="contractType"><option value="vacation" ${r.contractType==='vacation'?'selected':''}>Vacation directe</option><option value="interim" ${r.contractType==='interim'?'selected':''}>Intérim</option></select></div><div class="time-fields"><div class="field"><label>Taux horaire</label><input type="number" min="0" step="0.01" inputmode="decimal" name="rate" value="${r.rate||''}" placeholder="Ex. 37,50"></div><div class="field"><label>Repère</label><select name="rateBasis"><option value="net" ${r.rateBasis==='net'?'selected':''}>Net estimé</option><option value="brut" ${r.rateBasis==='brut'?'selected':''}>Brut</option></select></div></div><div class="time-fields"><div class="field"><label>Pause repas (min)</label><input type="number" min="0" step="5" inputmode="numeric" name="pauseMinutes" value="${r.pauseMinutes||''}" placeholder="Ex. 30"></div><div class="field"><label>Majoration intérim (%)</label><input type="number" min="0" max="100" step="1" inputmode="numeric" name="interimBonusPct" value="${r.interimBonusPct}" placeholder="20"></div><div class="field"><label>Net avant impôt (%)</label><input type="number" min="0" max="100" step="0.1" inputmode="decimal" name="interimNetPct" value="${r.interimNetPct}" placeholder="79,9"></div></div><p class="helper">En intérim, +20 % estime les congés payés et la fin de mission. Si le taux est en brut, 79,90 % estime le net avant prélèvement à la source. Le contrat et le bulletin restent la référence.</p></fieldset>`;
 openSheet(`${existing?'Modifier':'Nouvel'} établissement`, `<div class="field"><label>Nom de l’établissement</label><input required name="name" value="${escape(place.name)}" placeholder="Ex. Centre hospitalier"></div><div class="field"><label>Ville</label><input name="city" value="${escape(place.city)}" placeholder="Ex. Ville"></div><div class="field"><label>Service principal</label><input name="service" value="${escape(place.service)}" placeholder="Ex. Bloc opératoire"></div>${remunerationFields}<div class="field"><label>Repères personnels</label><textarea name="note" placeholder="Accès, vestiaires, habitudes utiles…">${escape(place.note)}</textarea></div>${attachmentsInput()}<div class="field"><label>Tags pour les fichiers ajoutés (facultatif)</label><div class="tag-picker">${tagOptions()}</div></div>`,async values=>{try{const files=values.attachments||[],tags=Array.isArray(values.tags)?values.tags:(values.tags?[values.tags]:[]);delete values.attachments;delete values.tags;const remuneration={contractType:values.contractType==='interim'?'interim':'vacation',rate:Math.max(0,Number(String(values.rate||'').replace(',','.'))||0),rateBasis:values.rateBasis==='brut'?'brut':'net',pauseMinutes:Math.max(0,Number(values.pauseMinutes)||0),interimBonusPct:Math.max(0,Number(values.interimBonusPct)===0?0:(Number(values.interimBonusPct)||20)),interimNetPct:Math.min(100,Math.max(0,Number(String(values.interimNetPct||'').replace(',','.'))===0?0:(Number(String(values.interimNetPct||'').replace(',','.'))||79.9)))};delete values.contractType;delete values.rate;delete values.rateBasis;delete values.pauseMinutes;delete values.interimBonusPct;delete values.interimNetPct;const added=await filesToResources(files,tags),list=getEstablishments();if(existing)setEstablishments(list.map(item=>item.id===existing.id?{...item,...values,remuneration,resources:[...placeResources(item),...added],attachment:null}:item));else setEstablishments([...list,{id:uid('est'),...values,remuneration,contacts:[],resources:added}]);establishments();toast(added.length?`Établissement et ${added.length} ressource${added.length>1?'s':''} enregistrés`:'Établissement enregistré');}catch(error){toast(error.message);throw error;}});
}

