 const today=new Date().toISOString().slice(0,10),planned=existing||{startDate:date||today,endDate:date||today,title:'',place:'',start:'',end:'',type:'work',note:'',attachment:null},first=eventStart(planned)||today,last=eventEnd(planned)||first,places=getEstablishments(),selectedId=planned.establishmentId||((places.find(x=>x.name===planned.place)||{}).id||'');
 const options=`<option value="">Aucun établissement enregistré</option>${places.map(place=>`<option value="${escape(place.id)}" ${place.id===selectedId?'selected':''}>${escape(place.name)}${rpReady(rpRemuneration(place))?' · rémunération réglée':''}</option>`).join('')}`;
