// RÉMUNÉRATION V45 — le travail réalisé et les versements sont suivis séparément.
function rpPayment(event={}){const status=['to-confirm','expected','received'].includes(event.paymentStatus)?event.paymentStatus:'to-confirm';const amount=Number(String(event.paymentAmount??'').replace(',','.'));return {status,amount:Number.isFinite(amount)&&amount>=0?amount:null,date:event.paymentDate||'',note:event.paymentNote||''};}
