function rpPaymentMonth(event){return rpPayment(event).date.slice(0,7);}
function rpDateLong(date){if(!date)return 'Date à confirmer';const value=new Date(`${date}T12:00:00`);return value.toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'});}
function rpMonthTitle(cursor){const [year,month]=cursor.split('-').map(Number);return `${monthLabels[month-1]} ${year}`;}
function rpMonthEvents(cursor){return getPlanning().filter(event=>event.type==='work'&&eventStart(event).slice(0,7)<=cursor&&eventEnd(event).slice(0,7)>=cursor);}
function rpWorkInMonth(event,cursor){return rpEstimate(event,rpDaysInMonth(event,cursor));}
