// V46 — Règle Intérim 12 : toutes les missions d’intérim d’un mois sont regroupées
// dans un seul versement, proposé le 12 du mois suivant. Les vacations directes restent séparées.
const getInterimPayments=()=>get('rp-interim-payments',[]);
const setInterimPayments=value=>set('rp-interim-payments',value);
backupCollections['rp-interim-payments']=[];
function rpIsInterim(event){const remuneration=rpSnapshot(event);return Boolean(event&&event.type==='work'&&remuneration&&remuneration.contractType==='interim');}
function rpNextMonthTwelfth(month){const [year,number]=month.split('-').map(Number),date=new Date(year,number,12);return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function rpInterimGroupKey(month){return `interim-${month}`;}
function rpInterimGroup(month){
 const events=getPlanning().filter(event=>rpIsInterim(event)&&eventStart(event).slice(0,7)<=month&&eventEnd(event).slice(0,7)>=month);
 const saved=getInterimPayments().find(item=>item.id===rpInterimGroupKey(month))||{};
 const estimatedAmount=events.reduce((sum,event)=>sum+rpEstimate(event,rpDaysInMonth(event,month)),0);
 const entered=Number(String(saved.paymentAmount??'').replace(',','.'));
 return {id:rpInterimGroupKey(month),workMonth:month,events,estimatedAmount,paymentAmount:Number.isFinite(entered)&&entered>=0?entered:null,paymentDate:saved.paymentDate||rpNextMonthTwelfth(month),paymentStatus:['to-confirm','expected','received'].includes(saved.paymentStatus)?saved.paymentStatus:'expected',paymentNote:saved.paymentNote||''};
}
function rpInterimGroups(){
 const months=new Set();getPlanning().forEach(event=>{if(!rpIsInterim(event))return;let month=eventStart(event).slice(0,7),end=eventEnd(event).slice(0,7);while(month<=end){months.add(month);const [year,number]=month.split('-').map(Number),next=new Date(year,number,1);month=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}`;}});return [...months].sort().map(rpInterimGroup);
}
function rpInterimPaymentAmount(group){return group.paymentAmount===null?group.estimatedAmount:group.paymentAmount;}
